preConditionHook:
// A triggered high-N long (low-N short) FAILS: after the count reached
// countTarget, price closes back beyond that signal bar's opposite extreme.
// Brooks reads a failed high 4 / low 4 as the side losing control and takes
// the trade in the OTHER direction -- so a failed high-N is this rule's SHORT
// and a failed low-N is its LONG.
//
// THE COUNTER IS THE SETTLED ONE (Ranges ch17, R17-01), inlined here as
// everywhere -- see HighLowBarCount for the full commentary. The failure test
// is nearly free on top of it: the signal bar's low is already retained at
// each advance, and this rule adds only a latch of that value at the
// countTarget advance plus a bars-since counter, which is what maxBarsSince
// bounds. The latch is guarded by a boolean rather than by its initial 0,
// because a back-adjusted continuous contract can print negative prices.
//
// The bars-since counters are incremented BEFORE the latch, so the latching
// bar itself reads 0 -- and on that bar the failure test cannot be true
// anyway, since the close cannot be below the same bar's own low.
//
// countTarget 4 is the case Brooks names most; the same input covers his
// failed low 1 (fading it in a bottoming bear trend) and failed low 2 / 3
// (the failed bear flag). Two sources add a conjunct that is NOT carried and
// is ANDed by the pane instead -- a trend-line break before the other side
// counts as having regained control, and the resulting breakout in the new
// direction.
priorHigh = high[1];
priorLow = low[1];
for (int i = 2; i <= (int)resetLookback; ++i) {
    if (el_gt(high[i], priorHigh)) priorHigh = high[i];
    if (el_lt(low[i], priorLow)) priorLow = low[i];
}
advHigh = false;
advLow = false;
if (el_gt(close[0], priorHigh)) {
    highCount = 0;
} else {
    if (el_lt(low[0], minLowSince)) minLowSince = low[0];
    if (el_gt(high[0], high[1]) && (highCount == 0 || el_lt(minLowSince, signalLow))) {
        highCount = highCount + 1;
        if (highCount > 4) highCount = 4;
        signalLow = low[0];
        minLowSince = low[0];
        advHigh = true;
    }
}
if (el_lt(close[0], priorLow)) {
    lowCount = 0;
} else {
    if (el_gt(high[0], maxHighSince)) maxHighSince = high[0];
    if (el_lt(low[0], low[1]) && (lowCount == 0 || el_gt(maxHighSince, signalHigh))) {
        lowCount = lowCount + 1;
        if (lowCount > 4) lowCount = 4;
        signalHigh = high[0];
        maxHighSince = high[0];
        advLow = true;
    }
}
if (haveHighTgt) barsSinceHighTgt = barsSinceHighTgt + 1;
if (haveLowTgt) barsSinceLowTgt = barsSinceLowTgt + 1;
if (advHigh && el_eq((double)highCount, countTarget)) {
    tgtSignalLow = low[0];
    haveHighTgt = true;
    barsSinceHighTgt = 0;
}
if (advLow && el_eq((double)lowCount, countTarget)) {
    tgtSignalHigh = high[0];
    haveLowTgt = true;
    barsSinceLowTgt = 0;
}
